#include <iostream>
#include <algorithm>
#include <vector>
#include <random>
#include <chrono>

int main() {
  std::vector<int> data(100000);
  std::mt19937 gen(std::chrono::system_clock::now().time_since_epoch().count());
  std::uniform_int_distribution<> distrib(1, 100000);
  std::generate(data.begin(), data.end(), [&](){ return distrib(gen); });

  auto start = std::chrono::high_resolution_clock::now();
  std::sort(data.begin(), data.end());
  auto end = std::chrono::high_resolution_clock::now();
  auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
  std::cout << "std::sort time: " << duration.count() << " ms" << std::endl;

  std::vector<int> data2 = data; //Copy for partial sort
  start = std::chrono::high_resolution_clock::now();
  std::partial_sort(data2.begin(), data2.begin() + 1000, data2.end()); //Sort only the first 1000 elements
  end = std::chrono::high_resolution_clock::now();
  duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
  std::cout << "std::partial_sort time: " << duration.count() << " ms" << std::endl;
  return 0;
}
